# -*- coding: utf-8 -*-
import os

from taf.playwright.core.artifacts import ArtifactManager
from taf.playwright.core.browser import BrowserManager
from taf.playwright.core.common import PlaywrightPagePart
from taf.playwright.core.debug import catch_interface_exception
from taf.playwright.core.session import SessionStore


class CoamFacade(object):
    """Minimal facade shared by Playwright COAM product libraries."""

    def __init__(self, session, screenshot_dir=None):
        self.session = session
        self.page = session.page
        self.screenshot_dir = screenshot_dir
        self.navigator = PlaywrightPagePart(self.page)

    def login(self, url, username, password, timeout=60):
        self.page.goto(url, wait_until="domcontentloaded", timeout=int(float(timeout) * 1000))
        self.navigator.fill('input[name="username"], input#username', username, timeout=timeout)
        self.navigator.fill('input[name="password"], input#password', password, timeout=timeout)
        try:
            self.page.get_by_role("button", name="Login").click(timeout=int(float(timeout) * 1000))
        except Exception:
            self.navigator.click("text=Login", timeout=timeout)

    def logout(self, timeout=10):
        self.navigator.optional_click(".user-account-view", timeout=2)
        self.navigator.optional_click("text=Logout", timeout=timeout)

    def save_screenshot(self, filename, screenshot_dir=None):
        target_dir = screenshot_dir or self.screenshot_dir or os.getcwd()
        if not os.path.exists(target_dir):
            os.makedirs(target_dir)
        path = os.path.join(target_dir, "{}.png".format(filename))
        self.page.screenshot(path=path, full_page=True)
        return path

    def navigate_route(self, route, timeout=60):
        for item in route:
            if not self.navigator.optional_click('text="{}"'.format(item), timeout=timeout):
                self.navigator.click("text={}".format(item), timeout=timeout)
        return True

    def close(self):
        self.session.close()


class CoamLibraryBase(object):
    """Robot library base for early Playwright COAM migration slices."""

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    DOWNLOAD_DIR_SUFFIX = "taf_playwright_coam_download"
    SCREENSHOT_DIR_SUFFIX = "taf_playwright_coam_screenshot"
    DEFAULT_CONFIGURATION_ROUTE = ("Configuration",)
    DEFAULT_DIAGNOSTIC_ROUTE = ("Diagnostics",)

    def __init__(self, browser_manager_factory=None, session_store=None):
        self._browser_manager_factory = browser_manager_factory or BrowserManager
        self._sessions = session_store or SessionStore()
        self._download_dir = None
        self._screenshot_dir = None
        self._artifacts = ArtifactManager(self.DOWNLOAD_DIR_SUFFIX, self.SCREENSHOT_DIR_SUFFIX)

    @property
    def download_dir(self):
        return self._download_dir

    @property
    def screenshot_dir(self):
        return self._screenshot_dir

    @catch_interface_exception
    def login(self, url, username, password, timeout=60, download_dir=None, screenshot_dir=None,
              browser="chromium", alias=None, headless=True, trace_dir=None, slow_mo=None):
        self._download_dir = self._artifacts.download_dir(download_dir)
        self._screenshot_dir = self._artifacts.screenshot_dir(self._download_dir, screenshot_dir)
        manager = self._browser_manager_factory(
            browser=browser,
            headless=headless,
            download_dir=self._download_dir,
            trace_dir=trace_dir,
            slow_mo=slow_mo,
        )
        session = manager.create_session()
        facade = CoamFacade(session, self._screenshot_dir)
        facade.login(url, username, password, timeout=timeout)
        self._sessions.add(facade, alias)

    @catch_interface_exception
    def logout(self, timeout=10, coam=None, close_browser=True):
        target = self._sessions.get(coam)
        target.logout(timeout=int(timeout))
        if str(close_browser).strip().lower() not in ("false", "0", "no", "off"):
            self._sessions.remove(coam)
            target.close()

    @catch_interface_exception
    def save_screenshot(self, filename, screenshot_dir=None, coam=None):
        return self._sessions.get(coam).save_screenshot(filename, screenshot_dir)

    @catch_interface_exception
    def go_to_configuration(self, timeout=60, coam=None):
        return self._sessions.get(coam).navigate_route(self.DEFAULT_CONFIGURATION_ROUTE, timeout=int(timeout))

    @catch_interface_exception
    def go_to_diagnostic(self, timeout=60, coam=None):
        return self._sessions.get(coam).navigate_route(self.DEFAULT_DIAGNOSTIC_ROUTE, timeout=int(timeout))

    def close_all(self):
        self._sessions.close_all()

    def list_aliases(self):
        return self._sessions.aliases()
